 out=ROOT/'runs/forecast-final-24576-v1';screen=ROOT/'runs/forecast-final-screen-v2';t=json.loads((out/'result.json').read_text());ev=json.loads((screen/'result.json').read_text());v=json.loads((out/'verification.json').read_text());rr=json.loads((screen/'records.json').read_text());roll=json.loads((out/'rollouts.json').read_text());summ=ev['summary'];head=summ['candidate_vs_outcome_60'];common=['ground','geometric'];cwin=sum(summ[f'candidate_vs_{b}_60']['W'] for b in common);owin=sum(summ[f'outcome_vs_{b}_60']['W'] for b in common)
